SELECT id, iccd, agent_name, phone_number, realname_id, realname_name, usage_status, card_status, operator_type, remark, create_time, update_time FROM phone_card
AND (iccd LIKE CONCAT('%', #{keyword}, '%') OR agent_name LIKE CONCAT('%', #{keyword}, '%') OR realname_name LIKE CONCAT('%', #{keyword}, '%'))
AND operator_type = #{operatorType}
AND usage_status = #{usageStatus}
AND card_status = #{cardStatus}
ORDER BY operator_type IS NULL, operator_type ASC, id DESC
ORDER BY agent_name IS NULL, agent_name ASC, id DESC
ORDER BY usage_status IS NULL, usage_status ASC, id DESC
ORDER BY realname_name IS NULL, realname_name ASC, id DESC
ORDER BY card_status IS NULL, card_status ASC, id DESC
ORDER BY id DESC
LIMIT #{offset}, #{limit}

